void toggleLibertyMidiInstrumentMute(MainComponent& owner);
namespace{
enum class Tool{select,draw,split,erase,resize,stretch,velocity,marquee,mute};
Tool activeTool=Tool::select;
const char* toolShortcuts[]={"1","2","3","4","5","6","7","8","9"};
bool paletteVisible=false;
int activeMode=0; // 0 Audio, 1 MIDI
class Palette final:public juce::Component{public:explicit Palette(MainComponent&o):owner(&o){setOpaque(true);audio.setButtonText("AUDIO");midi.setButtonText("MIDI");audio.setClickingTogglesState(true);midi.setClickingTogglesState(true);audio.setRadioGroupId(7101);midi.setRadioGroupId(7101);audio.setToggleState(true,juce::dontSendNotification);audio.onClick=[this]{modeMidi=false;activeMode=0;refresh();};midi.onClick=[this]{modeMidi=true;activeMode=1;refresh();};addAndMakeVisible(audio);addAndMakeVisible(midi);const char*names[]={"SELECT","DRAW","SPLIT","ERASE","RESIZE","STRETCH","VELOCITY","MARQUEE","MUTE"};for(int i=0;i<9;++i){buttons[i].setButtonText(names[i]);buttons[i].setClickingTogglesState(true);buttons[i].setRadioGroupId(7201);buttons[i].onClick=[this,i]{activeTool=(Tool)i;if(i==8&&modeMidi&&owner)toggleLibertyMidiInstrumentMute(*owner);refresh();};buttons[i].setTooltip(juce::String(names[i])+"  ["+toolShortcuts[i]+"]");addAndMakeVisible(buttons[i]);}refresh();}void paint(juce::Graphics&g)override{g.fillAll(juce::Colour(0xff11161c));g.setColour(juce::Colour(0xff63c7e8));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(1),6,1.5f);g.setColour(juce::Colour(0xffc9d2db));g.setFont(juce::Font(11,juce::Font::bold));g.drawText("LIBERTY TOOLS",10,5,getWidth()-20,20,juce::Justification::centredLeft);
for(int i=0;i<9;++i){auto b=buttons[i].getBounds();drawToolIcon(g,i,b);g.setColour(juce::Colour(0xff8e99a5));g.setFont(juce::Font(9.0f));g.drawText(toolShortcuts[i],b.getRight()-15,b.getY()+1,12,10,juce::Justification::centred);}}void resized()override{audio.setBounds(10,28,82,26);midi.setBounds(98,28,82,26);int x=10,y=62;for(int i=0;i<9;++i){buttons[i].setBounds(x,y,82,28);x+=88;if(x+82>getWidth()){x=10;y+=34;}}}void setMode(bool midiMode){modeMidi=midiMode;activeMode=midiMode?1:0;audio.setToggleState(!modeMidi,juce::dontSendNotification);midi.setToggleState(modeMidi,juce::dontSendNotification);refresh();}bool keyPressed(const juce::KeyPress& k) override {const auto ch=k.getTextCharacter();if(ch>='1'&&ch<='9'){const int i=(int)(ch-'1');if(buttons[i].isEnabled()){activeTool=(Tool)i;buttons[i].triggerClick();return true;}}return false;}private:void drawToolIcon(juce::Graphics&g,int i,juce::Rectangle<int>b){auto r=b.removeFromLeft(22).reduced(4);g.setColour(buttons[i].getToggleState()?juce::Colours::white:juce::Colour(0xff9fb0bd));g.setOpacity(buttons[i].isEnabled()?1.0f:0.35f);const float x=(float)r.getX(),y=(float)r.getY(),w=(float)r.getWidth(),h=(float)r.getHeight();juce::Path p;switch(i){case 0:p.startNewSubPath(x+2,y+1);p.lineTo(x+w-2,y+h*0.55f);p.lineTo(x+w*0.58f,y+h*0.62f);p.lineTo(x+w*0.78f,y+h-1);p.lineTo(x+w*0.60f,y+h);p.lineTo(x+w*0.42f,y+h*0.66f);p.lineTo(x+2,y+h-2);p.closeSubPath();g.fillPath(p);break;case 1:g.drawLine(x+2,y+h-2,x+w-3,y+3,2.2f);g.fillEllipse(x+w-5,y+1,4,4);break;case 2:g.drawEllipse(x+1,y+1,5,5,1.5f);g.drawEllipse(x+1,y+h-6,5,5,1.5f);g.drawLine(x+5,y+5,x+w-1,y+h-1,1.5f);g.drawLine(x+5,y+h-5,x+w-1,y+1,1.5f);break;case 3:g.fillRoundedRectangle(x+2,y+5,w-4,h-8,2);g.setColour(juce::Colour(0xff11161c));g.drawLine(x+5,y+h-5,x+w-5,y+7,1.3f);break;case 4:g.drawHorizontalLine((int)(y+h/2),x+2,x+w-2);g.drawLine(x+2,y+h/2,x+6,y+h/2-4,1.5f);g.drawLine(x+2,y+h/2,x+6,y+h/2+4,1.5f);g.drawLine(x+w-2,y+h/2,x+w-6,y+h/2-4,1.5f);g.drawLine(x+w-2,y+h/2,x+w-6,y+h/2+4,1.5f);break;case 5:g.drawLine(x+1,y+h/2,x+5,y+3,1.5f);g.drawLine(x+5,y+3,x+w-5,y+h-3,1.5f);g.drawLine(x+w-5,y+h-3,x+w-1,y+h/2,1.5f);g.drawLine(x+w-1,y+h/2,x+w-5,y+3,1.5f);break;case 6:for(int n=0;n<4;++n)g.fillRect((int)(x+2+n*3),(int)(y+h-2-(n+1)*3),2,(n+1)*3);break;case 7:{const float d[]={3.0f,2.0f};g.drawDashedLine(juce::Line<float>(x+1,y+2,x+w-1,y+2),d,2,2.0f);}{const float d[]={3.0f,2.0f};g.drawDashedLine(juce::Line<float>(x+w-1,y+2,x+w-1,y+h-2),d,2,2.0f);}{const float d[]={3.0f,2.0f};g.drawDashedLine(juce::Line<float>(x+w-1,y+h-2,x+1,y+h-2),d,2,2.0f);}{const float d[]={3.0f,2.0f};g.drawDashedLine(juce::Line<float>(x+1,y+h-2,x+1,y+2),d,2,2.0f);}break;case 8:g.drawRect((int)x+2,(int)y+5,(int)w-7,(int)h-10,1);p.startNewSubPath(x+w-5,y+6);p.lineTo(x+w-1,y+2);p.lineTo(x+w-1,y+h-2);p.lineTo(x+w-5,y+h-6);g.strokePath(p,juce::PathStrokeType(1.5f));g.drawLine(x+1,y+1,x+w-1,y+h-1,2);break;}g.setOpacity(1.0f);}void refresh(){for(int i=0;i<9;++i){bool allowed=modeMidi?(i==0||i==1||i==3||i==4||i==6||i==7||i==8):(i==0||i==2||i==3||i==4||i==5||i==8);buttons[i].setEnabled(allowed);buttons[i].setToggleState(allowed&&i==(int)activeTool,juce::dontSendNotification);
buttons[i].setColour(juce::TextButton::buttonColourId,(allowed&&i==(int)activeTool)?juce::Colour(0xff167c9f):juce::Colour(0xff252a31));
buttons[i].setColour(juce::TextButton::textColourOffId,(allowed&&i==(int)activeTool)?juce::Colours::white:juce::Colour(0xffd7dde3));}if(!buttons[(int)activeTool].isEnabled()){activeTool=Tool::select;}
buttons[0].setToggleState((int)activeTool==0,juce::dontSendNotification);
audio.setColour(juce::TextButton::buttonColourId,!modeMidi?juce::Colour(0xff167c9f):juce::Colour(0xff252a31));
midi.setColour(juce::TextButton::buttonColourId,modeMidi?juce::Colour(0xff167c9f):juce::Colour(0xff252a31));
repaint();} MainComponent* owner=nullptr;bool modeMidi=false;juce::TextButton audio,midi;std::array<juce::TextButton,9>buttons;};
class Controller:private juce::Timer{public:explicit Controller(MainComponent&o):owner(o){launcher.setButtonText("TOOLS");launcher.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff252a31));launcher.onClick=[this]{paletteVisible=!paletteVisible;if(box){box->setVisible(paletteVisible);if(paletteVisible){box->toFront(false);box->setWantsKeyboardFocus(true);box->grabKeyboardFocus();}}};owner.addAndMakeVisible(launcher);box=std::make_unique<Palette>(owner);owner.addChildComponent(*box);box->setVisible(false);owner.addKeyListener(&keys);keys.onKey=[this](const juce::KeyPress&k){if(!box)return false;const auto ch=k.getTextCharacter();if(ch=='a'||ch=='A'){box->setMode(false);return true;}if(ch=='m'||ch=='M'){box->setMode(true);return true;}return box->keyPressed(k);};startTimerHz(2);}~Controller(){shutdown();}void shutdown(){stopTimer();owner.removeKeyListener(&keys);box.reset();launcher.setVisible(false);}private:class Keys:public juce::KeyListener{public:std::function<bool(const juce::KeyPress&)>onKey;bool keyPressed(const juce::KeyPress&k,juce::Component*)override{return onKey?onKey(k):false;}}keys;void timerCallback()override{launcher.setBounds(558,8,74,26);launcher.toFront(false);if(box){int w=juce::jmin(380,juce::jmax(280,owner.getWidth()-40));box->setBounds(juce::jmax(10,(owner.getWidth()-w)/2),82,w,170);if(paletteVisible)box->toFront(false);}}MainComponent&owner;juce::TextButton launcher;std::unique_ptr<Palette>box;};std::map<MainComponent*,std::unique_ptr<Controller>>cs;class Boot:private juce::Timer{public:Boot(){startTimerHz(3);}~Boot(){shutdown();}void shutdown(){stopTimer();cs.clear();}private:void timerCallback()override{auto&d=juce::Desktop::getInstance();for(int i=0;i<d.getNumComponents();++i)if(auto*w=dynamic_cast<juce::DocumentWindow*>(d.getComponent(i)))if(auto*m=dynamic_cast<MainComponent*>(w->getContentComponent()))if(!cs.count(m))cs.emplace(m,std::make_unique<Controller>(*m));}}boot;}
int getLibertyActiveTool(){return(int)activeTool;}void shutdownLibertyToolPaletteController(){boot.shutdown();}
